begin;lock table public.campaigns,public.campaign_content_entries,public.campaign_state_fragments,public.campaign_character_versions,public.official_content_entries in share row exclusive mode;do $text$ begin if(select state_revision from public.campaigns where id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd')<>1711 then raise exception 'ITEM_TEXT_CAMPAIGN_CONFLICT';end if;if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:972c534ec917c0ce3dd1011d' and md5(to_jsonb(t)::text)='d0a338a3fa054743f0d375188231b3a3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:972c534ec917c0ce3dd1011d';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_ccab7911cb80d79b$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo bajo luz tenue o en la oscuridad, podrás lanzar a voluntad los conjuros luces danzantes y luz. Lanzar uno de estos conjuros desde el anillo requiere una acción.\n\nEl anillo tiene 6 cargas para utilizar las propiedades que se describen a continuación. Recupera 1d6 cargas empleadas cada día, al amanecer.\n\nFuego feérico. Como acción, puedes gastar 1 carga para lanzar fuego feérico desde el anillo.\n\nBola de rayos. Como acción, puedes gastar 2 cargas para crear entre una y cuatro esferas de rayos con un diámetro de 90 cm. Cuantas más esferas crees, menos potente será cada una de ellas.\n\nCada esfera aparece en un espacio sin ocupar que puedas ver a 36 m o menos de ti. Las esferas permanecerán hasta 1 minuto mientras mantengas la concentración (como si te concentraras en un conjuro). Cada una emite luz tenue en un radio de 9 m.\n\nComo acción adicional, puedes mover cada esfera hasta 9 m, pero no más allá de 36 m respecto a ti. Cuando una criatura que no seas tú se acerque a 1,5 m o menos de una esfera, esta descargará un relámpago sobre esa criatura y desaparecerá. La criatura deberá hacer una tirada de salvación de Destreza con CD 15. Si la falla, recibirá daño de relámpago según la cantidad de esferas que hayas creado.\n\n4 · 2d4\n3 · 2d6\n2 · 5d4\n1 · 4d12\n\nEstrellas fugaces. Como acción, puedes gastar entre 1 y 3 cargas. Por cada carga que emplees, lanzarás una mota de luz brillante desde el anillo hacia un punto que puedas ver a 18 m o menos de ti. A todas las criaturas situadas en un cubo de 4,5 m de lado que parta de ese punto les caerá una lluvia de chispas y deberán hacer una tirada de salvación de Destreza con CD 15. Sufrirán 5d4 de daño de fuego si la fallan o la mitad del daño si la superan.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ccab7911cb80d79b$::jsonb,true),'{rules,personalDescription}',$text_0e6a4d9cb9d0b4b7$"Mientras uses este anillo en la penumbra o en la oscuridad, puedes lanzar luces danzantes y luz desde el anillo a voluntad. Lanzar cualquiera de los hechizos desde el anillo requiere una acción. El anillo tiene 6 cargas para las siguientes otras propiedades. El anillo recupera 1d6 cargas gastadas diariamente al amanecer. Fuego feérico. Puedes gastar 1 carga como acción para lanzar fuego feérico desde el anillo. Relámpago esférico. Puedes gastar 2 cargas como acción para crear de una a cuatro esferas de relámpago de 3 pies de diámetro. Cuantas más esferas crees, menos poderosa será cada esfera individualmente. Cada esfera aparece en un espacio desocupado que puedes ver a 120 pies de ti. Las esferas duran mientras te concentres (como si te concentraras en un hechizo), hasta 1 minuto. Cada esfera arroja luz tenue en un radio de 30 pies.\nComo acción adicional, puedes mover cada esfera hasta 30 pies, pero no más allá de 120 pies de ti. Cuando una criatura que no seas tú se acerca a 5 pies de una esfera, la esfera descarga un rayo sobre esa criatura y desaparece. Esa criatura debe realizar una tirada de salvación de Destreza CD 15. Si falla la tirada, la criatura sufre daño por rayo según la cantidad de esferas que creaste.<br \n4-2d4\n3-2d6\n2-5d4\n1-4d12\n\nEstrellas fugaces. Puedes gastar de 1 a 3 cargas como acción. Por cada carga que gastes, lanzas una mota de luz brillante desde el anillo a un punto que puedas ver a 60 pies de ti. Cada criatura dentro de un cubo de 15 pies que se origine desde ese punto es bañada en chispas y debe realizar una tirada de salvación de Destreza CD 15, recibiendo 5d4 puntos de daño por fuego si falla la tirada, o la mitad de daño si tiene éxito."$text_0e6a4d9cb9d0b4b7$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:972c534ec917c0ce3dd1011d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:976d98f889add0f9fff0501e' and md5(to_jsonb(t)::text)='168e34a2837978c4b5c07a545af65e69')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:976d98f889add0f9fff0501e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_541b5e2a819fefef$[{"id":"official-use","kind":"other","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este mejunje parece, huele y sabe como una poción de curación u otra poción beneficiosa. Sin embargo, en realidad es un veneno enmascarado con magia de ilusionismo. Un conjuro identificar revelará su verdadera naturaleza.\n\nSi te bebes la poción, sufrirás 3d6 de daño de veneno y deberás superar una tirada de salvación de Constitución con CD 13 o quedarás envenenado. Al principio de cada uno de tus turnos mientras estés envenenado de esta forma, sufrirás 3d6 de daño de veneno. Al final de cada uno de tus turnos, podrás repetir la tirada de salvación. Si la superas, el daño de veneno que sufras en los turnos posteriores se reducirá en 1d6. El veneno dejará de tener efecto cuando el daño se reduzca a 0.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_541b5e2a819fefef$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:976d98f889add0f9fff0501e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9852ab1d5c8a0dd1a28350ee' and md5(to_jsonb(t)::text)='9d10517a977ce5ca5dda7b4647dfd1dd')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9852ab1d5c8a0dd1a28350ee';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_df4dbca6047bfaea$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta jabalina es un arma mágica. Cuando la lanzas y pronuncias su palabra de activación, se transforma en un relámpago y crea una línea de 1,5 m de ancho que se extiende desde ti hasta un objetivo a 36 m o menos. Todas las criaturas situadas en la línea (salvo el objetivo y tú) deberán hacer una tirada de salvación de Destreza con CD 13; sufrirán 4d6 de daño de relámpago si la fallan o la mitad del daño si la superan. El relámpago se convierte de nuevo en jabalina al alcanzar el objetivo. Haz un ataque con arma a distancia contra el objetivo. Si impacta, el objetivo recibe el daño de la jabalina más 4d6 de daño de relámpago.\n\nLa propiedad de la jabalina no podrá volver a usarse hasta el siguiente amanecer. Mientras tanto, la jabalina seguirá funcionando como arma mágica.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_df4dbca6047bfaea$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9852ab1d5c8a0dd1a28350ee';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:98f0c87fbcf5e4c229ee31c6' and md5(to_jsonb(t)::text)='6ad4413d66e0c4223eea5a430ffacc9a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:98f0c87fbcf5e4c229ee31c6';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_d6b671e160051085$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta elegante cadena de plata tiene un colgante con una gema negra de talla brillante. Mientras la lleves puesta, los venenos no te afectan. Eres inmune al estado de envenenado y tienes inmunidad al daño de veneno.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d6b671e160051085$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:98f0c87fbcf5e4c229ee31c6';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:998400e4c821f962aeb6cdd5' and md5(to_jsonb(t)::text)='e3f91f271c90924e61ac7f38b4e9cb89')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:998400e4c821f962aeb6cdd5';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_33f673615b476c36$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, tendrás resistencia al daño de frío. Además, las temperaturas de hasta −45 °C no os afectarán ni a ti ni a nada de lo que vistas o lleves.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_33f673615b476c36$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:998400e4c821f962aeb6cdd5';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9a1b04c90dc0a3418eadcb5a' and md5(to_jsonb(t)::text)='8512cf57460bcb5792df96abb5ca252a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9a1b04c90dc0a3418eadcb5a';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_d211c7a9b9bf3f24$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a la Clase de Armadura, las tiradas de salvación y las tiradas de ataque de conjuro.\n\nEl bastón tiene 20 cargas para utilizar las propiedades que se describen a continuación. El bastón recupera 2d8 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón conserva su bonifi- cador de +2 a las tiradas de ataque y de daño, pero pierde sus otras propiedades. Si el resultado es 20, el bastón recupera 1d8 + 2 cargas.\n\nGolpe de poder. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás gastar 1 carga para infligir 1d6 de daño de fuerza adicional al objetivo.\n\nConjuros. Mientras empuñes este bastón, puedes usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y bonificador de ataque de conjuro: bola de fuego (versión de nivel 5, 5 cargas), cono de frío (5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), muro de fuerza (5 cargas), proyectil mágico (1 carga), rayo debilitador (1 carga) o relámpago (versión de nivel 5, 5 cargas).\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón se puede usar a modo de bastón mágico que otorga un bonificador de +2 a las tiradas de ataque y de daño realizadas con él. Mientras lo empuñes, obtendrás un bonificador de +2 a la Clase de Armadura, las tiradas de salvación y las tiradas de ataque de conjuro.\n\nEl bastón tiene 20 cargas para utilizar las propiedades que se describen a continuación. El bastón recupera 2d8 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón conserva su bonifi- cador de +2 a las tiradas de ataque y de daño, pero pierde sus otras propiedades. Si el resultado es 20, el bastón recupera 1d8 + 2 cargas.\n\nGolpe de poder. Cuando impactes con un ataque cuerpo a cuerpo con el bastón, podrás gastar 1 carga para infligir 1d6 de daño de fuerza adicional al objetivo.\n\nConjuros. Mientras empuñes este bastón, puedes usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y bonificador de ataque de conjuro: bola de fuego (versión de nivel 5, 5 cargas), cono de frío (5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), muro de fuerza (5 cargas), proyectil mágico (1 carga), rayo debilitador (1 carga) o relámpago (versión de nivel 5, 5 cargas).\n\nGolpe vengador. Puedes usar una acción para romper el bastón de un rodillazo o contra una superficie sólida, lo que ejecuta un golpe vengador. El bastón se destruye y libera la magia que le queda a modo de explosión que se extiende para cubrir una esfera de 9 m de radio centrada en él.\n\nTienes un 50 por ciento de probabilidad de viajar en ese instante a un plano de existencia aleatorio y evitar la explosión. Si no logras evitar el efecto, sufrirás una cantidad de daño de fuerza igual a 16 veces el número de cargas del bastón. Todas las demás criaturas situadas en esa zona deberán hacer una tirada de salvación de Destreza con CD 17. Si la fallan, sufrirán daño conforme a la distancia a la que se encuentren del punto de origen, tal y como se muestra en la siguiente tabla. Si la superan, recibirán la mitad de ese daño.\n\n3 m de distancia o más · 8 veces el número de cargas\ncerca · del bastón\nDe 4 m a 6 m de · 6 veces el número de cargas\ndistancia · del bastón\nDe 7 m a 9 m de · 4 veces el número de cargas\ndistancia · del bastón\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_d211c7a9b9bf3f24$::jsonb,true),'{rules,personalDescription}',$text_41115f2e081bd272$"Este bastón puede ser usado como un bastón mágico que otorga un bonificador +2 a las tiradas de ataque y daño realizadas con él. Mientras lo sostienes, obtienes un bonificador +2 a la Clase de Armadura, a las tiradas de salvación y a las tiradas de ataque con conjuros. El bastón tiene 20 cargas para las siguientes propiedades. El bastón recupera 2d8 + 4 cargas gastadas diariamente al amanecer. Si gastas la última carga, tira un d20. Con un 1, el bastón conserva su bonificador +2 a las tiradas de ataque y daño, pero pierde todas las demás propiedades. Con un 20, el bastón recupera 1d8 + 2 cargas. \n-Golpe poderoso. Cuando realizas un ataque cuerpo a cuerpo con el bastón, puedes gastar 1 carga para infligir 1d6 puntos de daño de fuerza adicional al objetivo. \n-Hechizos. Mientras sostienes este bastón, puedes usar una acción para gastar 1 o más de sus cargas para lanzar uno de los siguientes hechizos desde él, usando tu CD de salvación de hechizos y tu bonificación de ataque de hechizos: cono de frío (5 cargas), bola de fuego (versión de nivel 5, 5 cargas), globo de invulnerabilidad (6 cargas), inmovilizar monstruo (5 cargas), levitar (2 cargas), rayo (versión de nivel 5, 5 cargas), proyectil mágico (1 carga), rayo de debilitamiento (1 carga) o muro de fuerza (5 cargas). \n-Golpe retributivo. Puedes usar una acción para romper el bastón sobre tu rodilla o contra una superficie sólida, realizando un golpe retributivo. El bastón se destruye y libera su magia restante en una explosión que se expande para llenar una esfera de 30 pies de radio centrada en él. Tienes un 50 por ciento de probabilidad de viajar instantáneamente a un plano de existencia aleatorio, evitando la explosión. Si no logras evitar el efecto, recibes daño de fuerza igual a 16 × el número de cargas en el bastón. Todas las demás criaturas en el área deben realizar una tirada de salvación de Destreza CD 17. Si falla la tirada de salvación, una criatura recibe una cantidad de daño basada en lo lejos que está del punto de origen, como se muestra en la siguiente tabla. Si tiene éxito, una criatura recibe la mitad de daño.\n-10 pies de distancia o más cerca - 8 veces la cantidad de cargas en el bastón\n-11 a 20 pies de distancia - 6 veces la cantidad de cargas en el bastón\n-21 a 30 pies de distancia - 4 veces la cantidad de cargas en el bastón"$text_41115f2e081bd272$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9a1b04c90dc0a3418eadcb5a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9aa7b625b0a1d2f57d2321e2' and md5(to_jsonb(t)::text)='be2284264e1dc13db8bcc406db914bfc')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9aa7b625b0a1d2f57d2321e2';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_249d9877e6e0199e$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, tu puntuación de Fuerza cambiará durante 1 hora. El tipo de gigante determina la puntuación (consulta la tabla más adelante). La poción no tendrá ningún efecto si tu Fuerza es igual o superior a esa puntuación.\n\nEn el líquido transparente de la poción flota un trozo de uña de un gigante del tipo correspondiente. La poción de fuerza de gigante de escarcha y la poción de fuerza de gigante de piedra tienen el mismo efecto.\n\nGigante de las colinas · 21 · Infrecuente\nGigante de escarcha/piedra · 23 · Rara\nGigante de fuego · 25 · Rara\nGigante de las nubes · 27 · Muy rara\nGigante de las tormentas · 29 · Legendaria\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_249d9877e6e0199e$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9aa7b625b0a1d2f57d2321e2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ae2f695fea4ba034c965e44' and md5(to_jsonb(t)::text)='f7d2d36027417564045b3076e5d86cdb')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9ae2f695fea4ba034c965e44';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b0fdb5e9b42a7c29$[{"id":"verified-passive-bonuses","kind":"passive","name":"Bonos del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta varita, obtendrás un bonificador a las tiradas de ataque de conjuro determinado por la rareza de la varita. Además, ignorarás la cobertura media cuando realices un ataque de conjuro.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b0fdb5e9b42a7c29$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ae2f695fea4ba034c965e44';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ae6ae5860d49581cf79ae66' and md5(to_jsonb(t)::text)='4c57a2f5d35cf9f49b1172b024f520d0')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9ae6ae5860d49581cf79ae66';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_63a771c872356136$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este bastón tiene 10 cargas. Mientras lo empuñes, podrás usar una acción y gastar 1 o más de sus cargas para lanzar uno de los siguientes conjuros desde él con tu CD de salvación de conjuros y modificador por aptitud mágica: curar heridas (1 carga por nivel del conjuro, hasta el 4), curar heridas en masa (5 cargas), restablecimiento menor (2 cargas).\n\nEl bastón recupera 1d6 + 4 cargas empleadas cada día, al amanecer. Si gastas la última carga, tira 1d20. Si el resultado es 1, el bastón se desvanece tras un destello y se pierde para siempre.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_63a771c872356136$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ae6ae5860d49581cf79ae66';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9b4e2e201ea30fe2d31e4c16' and md5(to_jsonb(t)::text)='1ebb9be50783be20bf3ea9bc6f46c6d3')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9b4e2e201ea30fe2d31e4c16';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_731eca42d466f6e0$[{"id":"official-base-table","rows":[["Honda","1 pp","—","1d4 contundente","+0","Munición","30/120"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_731eca42d466f6e0$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_f8d22033b8f87943$["official-base-table","property-ammunition","family-rule"]$text_f8d22033b8f87943$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9b4e2e201ea30fe2d31e4c16';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9c016be8b83c12338a8dad61' and md5(to_jsonb(t)::text)='2a73a4fe1073873b56ed61a6cfbe68de')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9c016be8b83c12338a8dad61';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_ed733db2dc34fc1b$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Estas herraduras de hierro vienen de cuatro en cuatro. Mientras cuatro de ellas estén fijadas a los cascos de un caballo o de una criatura similar, aumentarán su velocidad caminando en 9 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_ed733db2dc34fc1b$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9c016be8b83c12338a8dad61';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9d725e129a9bf59a7ba9ff76' and md5(to_jsonb(t)::text)='3bddff100c7f5876665570a02e8b14ba')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9d725e129a9bf59a7ba9ff76';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_5ef3dd6f41cbc226$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta varita tiene 7 cargas. Mientras la empuñes, podrás usar una acción y gastar 1 de sus cargas para lanzar el conjuro polimorfar (CD de salvación 15) desde ella.\n\nLa varita recupera 1d6 + 1 cargas empleadas cada día, al amanecer. Si gastas la última carga de la varita, tira 1d20. Si el resultado es 1, la varita se convierte en cenizas y se destruye.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5ef3dd6f41cbc226$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9d725e129a9bf59a7ba9ff76';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9e57f5c2c50cbb85a56cb9e4' and md5(to_jsonb(t)::text)='b2a8279a36a9d874aec3acb785669438')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9e57f5c2c50cbb85a56cb9e4';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_f05eb5a58a543e6e$[{"id":"legacy-bonus-0","kind":"passive","name":"SpellAttackandSave","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador de +2 a las tiradas de ataque de hechizos y a las CD de las tiradas de salvación de tus hechizos.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta elegante prenda está hecha de una tela exquisita de color blanco, gris o negro y va adornada con runas plateadas. El color de la túnica se corresponde con el alineamiento para el que se ha creado el objeto. La túnica blanca se ha fabricado para alguien bueno, la gris, para alguien neutral, y la negra, para alguien malvado. No puedes sintonizarte con una túnica del archimago que no se corresponda con tu alineamiento.\n\nMientras lleves puesta la túnica, obtendrás los siguientes beneficios: • Si no llevas armadura, tu Clase de Armadura base será de 15 + tu modificador por Destreza. • Tienes ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos. • Tu CD de salvación de conjuros y tu bonificador de ataque de conjuros aumentan en 2.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f05eb5a58a543e6e$::jsonb,true),'{rules,personalDescription}',$text_fd7cf97f8509816d$"Esta elegante prenda está hecha de una tela exquisita de color blanco, gris o negro y adornada con runas plateadas. Mientras la lleves puesta, obtendrás los siguientes beneficios:\n\nArmor. Mientras no vistas armadura alguna, tu CA será de 15 + tu modificador por Destreza.\n\nTienes ventaja en las tiradas de salvación para evitar conjuros y otros efectos mágicos.\n\nTu CD de salvación de conjuros y tu bonificador de ataque para conjuros aumentan en 2."$text_fd7cf97f8509816d$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9e57f5c2c50cbb85a56cb9e4';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ed0f1f2ba370de4d8d74dcc' and md5(to_jsonb(t)::text)='42ca969eb536a0e232449e31e33c2188')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:9ed0f1f2ba370de4d8d74dcc';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_f5eb42759beae224$[{"id":"official-base-table","rows":[["Espada larga","15 po","3 lb","1d8 cortante","+0","Versátil","1d10"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Daño versátil"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-versatile","text":"Versátil. Estas armas pueden utilizarse con una o con dos manos. Tras esta propiedad aparece entre paréntesis un valor de daño, que será el que uses cuando emplees esta arma a dos manos para hacer un ataque cuerpo a cuerpo.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_f5eb42759beae224$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_5488757723349d23$["official-base-table","property-versatile","family-rule"]$text_5488757723349d23$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:9ed0f1f2ba370de4d8d74dcc';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a1046d202eac24eb208cce1a' and md5(to_jsonb(t)::text)='55a063d114ffd40ba642780bd068015a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a1046d202eac24eb208cce1a';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_b40b5f9186ea5148$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Tienes un bonificador a las tiradas de ataque y de daño que hagas con esta unidad de munición mágica. El bonificador depende de la rareza de la munición. Una vez que impacte en un objetivo, la munición dejará de ser mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_b40b5f9186ea5148$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a1046d202eac24eb208cce1a';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a1a97cd87f765da9a3ab9af1' and md5(to_jsonb(t)::text)='1e1e4158652e67cbe8924a0c18e15ac7')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a1a97cd87f765da9a3ab9af1';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_3845e013f3642086$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras empuñes esta vara, podrás utilizar tu reacción para absorber un conjuro que solo te haga objetivo a ti y no tenga un área de efecto. El efecto del conjuro absorbido se cancelará y la energía del conjuro (no el conjuro en sí) se almacenará en la vara. La energía tiene el mismo nivel que el conjuro cuando se lanzó. La vara puede absorber y almacenar hasta 50 niveles de energía a lo largo de su existencia. En cuanto la vara absorba 50 niveles de energía, no podrá absorber más. Si eres el objetivo de un conjuro que la vara no puede almacenar, esta no tendrá efecto sobre ese conjuro.\n\nCuando te sintonizas con la vara, sabes cuántos niveles de energía ha absorbido a lo largo de su existencia y cuántos niveles de energía de conjuro están almacenados en ella en ese momento.\n\nSi eres un lanzador de conjuros y empuñas esta vara, podrás convertir la energía almacenada en ella en espacios de conjuro para lanzar conjuros que hayas preparado o conozcas. Solamente puedes crear espacios de conjuro de un nivel igual o inferior al mayor de tus espacios de conjuro, como máximo de nivel 5. Puedes utilizar los niveles almacenados en lugar de tus espacios de conjuro, pero, por lo demás, lanzarás el conjuro de forma normal. Por ejemplo, puedes utilizar 3 niveles almacenados en la vara como un espacio de conjuro de nivel 3.\n\nUna vara recién encontrada tiene 1d10 niveles de energía de conjuros ya almacenados. Una vara que ya no pueda absorber la energía de los conjuros y a la que no le quede nada de energía almacenada se volverá no mágica.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_3845e013f3642086$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a1a97cd87f765da9a3ab9af1';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a2667f9e44b993a8c4bedb72' and md5(to_jsonb(t)::text)='1ac5e0c87128e8081f0ce8db159f3559')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a2667f9e44b993a8c4bedb72';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_e8c12aef4714320a$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este collar tiene 1d4 + 2 cuentas mágicas hechas de aguamarina, perla negra o topacio. También posee muchas cuentas no mágicas hechas de piedras como ámbar, citrino, coral, cuarzo, jade, perla o sanguino. Si se retira una cuenta mágica del collar, esta pierde su magia.\n\nExisten seis tipos de cuentas mágicas. Tu GM decide el tipo de cada cuenta del collar o lo determina al azar. Un collar puede tener más de una cuenta del mismo tipo. Para usar una, debes llevar puesto el collar. Cada cuenta alberga un conjuro que puedes lanzar desde ella como acción adicional (usa tu CD de salvación de conjuros si fuera necesaria una tirada de salvación). Una vez que se lanza el conjuro de una cuenta mágica, esa cuenta no puede volver a usarse hasta el siguiente amanecer.\n\n1–6 · Bendita · Bendición\n07–08 · Castigadora Curativa · Castigo marcador Curar heridas (nivel 2)\n09–14 ·  · o restablecimiento menor\n15–18 · Favorecedora · Restablecimiento mayor\n19 · Invocadora · Aliado planar\n20 · Viajante · Viajar con el viento\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e8c12aef4714320a$::jsonb,true),'{rules,personalDescription}',$text_6876874824f31112$"Este collar tiene ld4 + 2 cuentas mágicas hechas de agua marina, perla negra o topacio. También posee muchas otras cuentas no mágicas fabricadas con gemas como ámbar, jaspe sanguíneo, citrino, coral, jade, perla o cuarzo. S i se retira una cuenta mágica del collar, pierde su magia. Existen seis tipos de cuentas mágicas. El DM decide el tipo de cada cuenta o lo determina al azar. Un collar puede tener más de una cuenta del mismo tipo. Para usar una, debes llevar puesto el collar. Cada cuenta contiene un conjuro que puedes lanzar empleando una acción adicional (utilizando tu CD de salvación de conjuros, si fuera necesaria una tirada de salvación). Una vez se lanza el conjuro de una cuenta mágica, esta no puede volver a emplearse hasta la mañana siguiente.\n\n1-6 - Bendita - Bendición\n7-12 - Curativa - Curar heridas (nivel 2) o restablecimiento menor\n13-16 - De favor divino  - Restablecimiento mayor\n17-18 - Castigadora - Castigo marcador\n19 - Invocadora - Aliado planar\n20 - De caminar los vientos  - Viajar con el viento"$text_6876874824f31112$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a2667f9e44b993a8c4bedb72';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a2e56acba61a14b044864300' and md5(to_jsonb(t)::text)='1e3b7ea7ff2084097d23f13efe6297c2')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a2e56acba61a14b044864300';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_e8ebd7c22c70998e$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este frasco de hierro tiene un tapón de latón. Puedes usar una acción para pronunciar la palabra de activación del frasco y hacer objetivo a una criatura que puedas ver a 18 m o menos de ti. Si el objetivo pertenece a un plano de existencia distinto al actual, deberá superar una tirada de salvación de Sabiduría con CD 17 o quedará atrapado en el frasco. Si el objetivo ya ha estado encerrado antes en el frasco, tendrá ventaja en la tirada de salvación. Una vez atrapada, la criatura permanecerá en el frasco hasta que sea liberada. El frasco solo puede contener a una criatura a la vez. Una criatura atrapada en el frasco no necesita respirar ni comer ni beber, y no envejece.\n\nPuedes usar una acción para quitar el tapón del frasco y liberar a la criatura que contenga. La criatura es amistosa contigo y tus compañeros durante 1 hora y obedece tus órdenes durante ese tiempo. Si no le das ninguna orden o le das una orden que probablemente desemboque en su muerte, se defenderá, pero no realizará ninguna otra acción. Al final de la duración, la criatura actuará conforme a su carácter y alineamiento normales.\n\nUn conjuro identificar revela que una criatura se encuentra en el interior del frasco, pero la única forma de saber de qué criatura se trata es abrir el frasco. Un frasco recién descubierto podría contener una criatura elegida por tu GM o determinada al azar.\n\n1–50 · Vacío\n51–53 · Acechador invisible\n54–57 · Demonio (tipo 1)\n58–61 · Demonio (tipo 2)\n62–65 · Demonio (tipo 3)\n66–67 · Demonio (tipo 4)\n68 · Demonio (tipo 5)\n69 · Demonio (tipo 6)\n70 · Deva\n71–72 · Diablo (mayor)\n73–76 · Diablo (menor)\n77–78 · Djinn\n79–84 · Elemental (cualquiera)\n85–86 · Ifrit\n87 · Planetar\n88–91 · Saga de la noche\n92–95 · Salamandra\n96 · Solar\n97–99 · Súcubo/íncubo\n100 · Xorn\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_e8ebd7c22c70998e$::jsonb,true),'{rules,personalDescription}',$text_6d45492513beaa6c$"Esta botella de hierro tiene un tapón de latón. Puedes usar una acción para pronunciar la palabra de activación del frasco, eligiendo como objetivo una criatura que puedas ver y que se encuentre a 60 pies o menos de ti. Si el objetivo es nativo de un plano de existencia distinto al actual, deberá tener éxito en una tirada de salvación CD 17 o que dará atrapado en el frasco. Si ya ha sido apresado en él con anterioridad, tendrá ventaja en la tirada de salvación. Una vez encerrada, la criatura permanecerá en el frasco hasta que sea liberada. Este objeto solo puede contener a un objetivo a l mismo tiempo. Mientras permanezca atrapada, la criatura no envejecerá y, además, no necesitará comer, beber ni respirar. Puedes utilizar una acción para quitar el tapón y liberar a la criatura contenida. Esta será amistosa hacia ti y tus compañeros durante 1 hora, obedeciendo tus órdenes durante ese tiempo. Si no le das ninguna orden o le encargas una tarea que pudiera desembocar en su muerte, se defenderá, pero no tomará otro tipo de acciones. Al final de la duración, la criatura actuará de acuerdo a su disposición y alinea miento habituales. El conjuro identificar revela que una criatura está dentro del frasco, pero la única manera de saber de qué tipo se trata es abrir dicho recipiente. Una botella recién descubierta podría contener una criatura, elegida por el DM o determinada al azar.\n\n1-50 - Vacía - 77-78 - Elemental (cualquiera)\n51 - Arcanaloth - 79 - Caballero githyanki\n52 - Cambion - 80 - Zerth githzerai\n53-54 - Dao - 81-82 - Acechador invisible\n55-57 - Demonio (tipo 1) - 83-84 - Marid\n58-60 - Demonio (tipo 2) - 85-86 - Mezzoloth\n61-62 - Demonio (tipo 3) - 87-88 - Saga de la noche\n63-64 - Demonio (tipo 4) - 89-90 - Nycaloth\n65 - Demonio (tipo 5) - 91 - Planetar\n66 - Demonio (tipo 6) - 92-93 - Salamandra\n67 - Deva - 94-95 - Slaad (cualquiera)\n68-69 - Diablo (mayor) - 96 - Solar\n70-72 - Diablo (menor) - 97-98 - Súcubo/ Íncubo\n73-74 - Djinni - 99 - Ultroloth\n75-76 - lfrit - 00 - Xorn"$text_6d45492513beaa6c$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a2e56acba61a14b044864300';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a4f727299e81bee097f0d666' and md5(to_jsonb(t)::text)='533e7aa63f929f3c886bbfc4dedeba23')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a4f727299e81bee097f0d666';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_2da9ec54e25345aa$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Este cetro tiene una cabeza con reborde y funciona como una maza mágica que otorga un bonificador de +3 a las tiradas de ataque y de daño hechas con ella. Además, tiene propiedades asociadas a seis botones dispuestos en fila a lo largo de la empuñadura. También cuenta con otras tres propiedades, descritas a continuación.\n\nSeis botones. Puedes pulsar uno de los seis botones del cetro como acción adicional. El efecto del botón dura hasta que pulses un botón distinto o hasta que pulses de nuevo el mismo botón, lo que hace que el cetro recupere su forma normal.\n\nSi pulsas el botón 1, el cetro se convierte en una lengua de fuego, ya que una hoja llameante surge del extremo opuesto a la cabeza rebordeada.\n\nSi pulsas el botón 2, la cabeza rebordeada del cetro se pliega sobre sí misma y surgen dos hojas con forma de media luna en su lugar, lo que transforma el cetro en un hacha de guerra mágica que otorga un bonificador de +3 a las tiradas de ataque y de daño hechas con ella.\n\nSi pulsas el botón 3, la cabeza rebordeada del cetro se pliega sobre sí misma, la punta de una lanza surge en su lugar y la empuñadura del cetro se alarga hasta medir 1,8 m, lo que lo transforma en una lanza mágica que otorga un bonificador de +3 a las tiradas de ataque y de daño hechas con ella.\n\nSi pulsas el botón 4, el cetro se transforma en una pértiga tan larga como especifiques, hasta un máximo de 15 m. En las superficies tan duras como el granito, aparecen una punta en la parte inferior y tres ganchos en la parte superior para fijar la pértiga. Además, en los laterales se despliegan unas barras horizontales de 7,5 cm de largo con una separación de 30 cm entre sí para formar una escalera. La pértiga puede soportar hasta 2000 kg. Si carga con más peso o si no tiene un anclaje sólido, el cetro recupera su formal normal.\n\nSi pulsas el botón 5, el cetro se transforma en un ariete portátil y otorga a su usuario un bonificador de +10 a las pruebas de Fuerzas realizadas para derribar puertas, barricadas u otro tipo de barrera.\n\nSi pulsas el botón 6, el cetro adopta o recupera su forma normal e indica el norte magnético (no ocurrirá nada si esta función del cetro se utiliza en un lugar que carezca de norte magnético). El cetro también te permite saber tu profundidad aproximada bajo tierra o tu altitud si estás en la superficie.\n\nAterrorizar. Mientras empuñes el cetro, podrás utilizar una acción para obligar a todas las criaturas que puedas ver a 9 m o menos de ti a realizar una tirada de salvación de Sabiduría con CD 17. Si la fallan, quedarán asustadas de ti durante 1 minuto. Un objetivo asustado puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nDrenar vida. Cuando impactes a una criatura con un ataque cuerpo a cuerpo usando el cetro, podrás obligar al objetivo a realizar una tirada de salvación de Constitución con CD 17. Si la falla, sufrirá 4d6 de daño necrótico adicional y tú recuperarás una cantidad de puntos de golpe igual a la mitad de ese daño necrótico. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nParalizar. Cuando impactes a una criatura con un ataque cuerpo a cuerpo usando el cetro, podrás obligar al objetivo a realizar una tirada de salvación de Fuerza con CD 17. Si la falla, el objetivo quedará paralizado durante 1 minuto. El objetivo puede repetir la tirada de salvación al final de cada uno de sus turnos y, si tiene éxito, se librará del efecto. Esta propiedad no podrá volver a usarse hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_2da9ec54e25345aa$::jsonb,true),'{rules,personalDescription}',$text_46e25067c2daedae$"Esta vara tiene una cabeza con reborde y funciona como una maza mágica que otorga una bonificación de +3 a las tiradas de ataque y daño realizadas con ella. La vara tiene propiedades asociadas con seis botones diferentes que están dispuestos en fila a lo largo del mango. También tiene otras tres propiedades, que se detallan a continuación. Seis botones. Puedes presionar uno de los seis botones de la vara como acción adicional. El efecto de un botón dura hasta que presiones un botón diferente o hasta que presiones el mismo botón nuevamente, lo que hace que la vara vuelva a su forma normal. \n-Si presionas el botón 1, la vara se convierte en una lengua de fuego, mientras una hoja de fuego brota del extremo opuesto a la cabeza con brida de la vara (tú eliges el tipo de espada). \n-Si presionas el botón 2, la cabeza con brida de la varilla se pliega hacia abajo y surgen dos hojas con forma de medialuna, transformando la varilla en un hacha de batalla mágica que otorga una bonificación de +3 a las tiradas de ataque y daño realizadas con ella. \n-Si presionas el botón 3, la cabeza con brida de la vara se pliega hacia abajo, una punta de lanza surge de la punta de la vara y el mango de la vara se alarga hasta convertirse en un mango de 6 pies, transformando la vara en una lanza mágica que otorga una bonificación de +3 a las tiradas de ataque y daño realizadas con ella. \n-Si presiona el botón 4, la barra se transforma en un poste de escalada de hasta 50 pies de largo, según lo especifique. En superficies tan duras como el granito, una punta en la parte inferior y tres ganchos en la parte superior anclan el poste. Las barras horizontales de 3 pulgadas de largo se despliegan desde los lados, a 1 pie de distancia, formando una escalera. El poste puede soportar hasta 4000 libras. Más peso o la falta de anclaje sólido hacen que la barra vuelva a su forma normal. \n-Si presiona el botón 5, la vara se transforma en un ariete portátil y otorga a su usuario una bonificación de +10 a las pruebas de Fuerza realizadas para atravesar puertas, barricadas y otras barreras. \n-Si pulsa el botón 6, la varilla adopta o permanece en su forma normal e indica el norte magnético. (No ocurre nada si se utiliza esta función de la varilla en un lugar que no tiene norte magnético). La varilla también le permite saber su profundidad aproximada bajo el suelo o su altura sobre él. \n-Drenar vida. Cuando golpeas a una criatura con un ataque cuerpo a cuerpo usando la vara, puedes obligar al objetivo a realizar una tirada de salvación de Constitución CD 17. Si falla, el objetivo sufre 4d6 puntos de daño necrótico adicionales y tú recuperas una cantidad de puntos de golpe igual a la mitad de ese daño necrótico. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer. \n-Paralizar. Cuando golpeas a una criatura con un ataque cuerpo a cuerpo usando la vara, puedes obligar al objetivo a realizar una tirada de salvación de Fuerza CD 17. Si falla, el objetivo queda paralizado durante 1 minuto. El objetivo puede repetir la tirada de salvación al final de cada uno de sus turnos, y el efecto finaliza si tiene éxito. Esta propiedad no se puede volver a utilizar hasta el siguiente amanecer. \n-Aterrorizar. Mientras sostienes la vara, puedes usar una acción para obligar a cada criatura que puedas ver a 30 pies de ti a realizar una tirada de salvación de Sabiduría CD 17. Si falla, un objetivo se asusta de ti durante 1 minuto. Un objetivo asustado puede repetir la tirada de salvación al final de cada uno de sus turnos, terminando el efecto sobre sí mismo si tiene éxito. Esta propiedad no se puede volver a usar hasta el próximo amanecer."$text_46e25067c2daedae$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a4f727299e81bee097f0d666';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a5a38836a0abdf55d85abd49' and md5(to_jsonb(t)::text)='00e115740aa350827dbc9691e05ff6a4')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a5a38836a0abdf55d85abd49';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_0e8e27d117c2dade$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este anillo, podrás volverte invisible como acción. Cualquier cosa que vistas o lleves será invisible también. Permanecerás invisible hasta que te quites el anillo, ataques, lances un conjuro o utilices una acción adicional para volverte visible de nuevo.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_0e8e27d117c2dade$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a5a38836a0abdf55d85abd49';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a75d7e0eba6a1f4a6b03546d' and md5(to_jsonb(t)::text)='19863b117925598a739fe68371be3323')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a75d7e0eba6a1f4a6b03546d';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_931f52f13fa3a9dc$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta caja contiene una baraja de cartas de pergamino. Una baraja completa tiene 34 cartas. A una baraja encontrada como tesoro le suelen faltar 1d20 − 1 cartas.\n\nLa magia de la baraja funciona solo si las cartas se roban al azar (puedes usar una baraja de naipes alterada para simular esta baraja). Puedes utilizar una acción para robar una carta al azar de la baraja y tirarla al suelo, a un punto que esté a 9 m o menos de ti.\n\nSe formará una ilusión compuesta por una o varias criaturas sobre la carta tirada y permanecerá hasta que se disipe. Las criaturas ilusorias parecen reales, del tamaño apropiado, y se comportan como si fueran la verdadera criatura salvo que no pueden infligir daño. Mientras estés a 36 m o menos de una criatura ilusoria y puedas verla, podrás emplear una acción para moverla mágicamente a cualquier lugar situado a 9 m o menos de la carta. Cualquier interacción física con la criatura ilusoria revelará que se trata de una ilusión, ya que los objetos la atravesarán. Si alguien utiliza una acción para inspeccionar a la criatura visualmente, se percatará de que es una ilusión si supera una prueba de Inteligencia (Investigación) con CD 15. La criatura se mostrará translúcida en ese caso.\n\nLa ilusión durará hasta que se disipe o hasta que alguien mueva la carta. Cuando la ilusión concluya, la imagen de la carta desaparecerá y esa carta no se podrá volver a usar.\n\nAs de corazones · Dragón rojo\nRey de corazones · Caballero y cuatro guardias\nReina de corazones · Súcubo o íncubo\nJota de corazones · Druida\nDiez de corazones · Gigante de las nubes\nNueve de corazones · Ettin\nOcho de corazones · Osgo\nDos de corazones · Goblin\nAs de diamantes · Contemplador\nRey de diamantes · Archimago y aprendiz de mago\nReina de diamantes · Saga de la noche\nJota de diamantes · Asesino\nDiez de diamantes · Gigante de fuego\nNueve de diamantes · Ogro mago\nOcho de diamantes · Gnoll\nDos de diamantes · Kobold\nAs de picas · Liche\nRey de picas · Sacerdote y dos acólitos\nReina de picas · Medusa\nJota de picas · Veterano\nDiez de picas · Gigante de escarcha\nNueve de picas · Troll\nOcho de picas · Hobgoblin\nDos de picas · Goblin\nAs de tréboles · Gólem de hierro\nRey de tréboles · Capitán bandido y tres bandidos\nReina de tréboles · Erinia\nJota de tréboles · Berserker\nDiez de tréboles · Gigante de las colinas\nNueve de tréboles · Ogro\nOcho de tréboles · Orco\nDos de tréboles · Kobold\nComodines (2) · Tú (quien posee la baraja)\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_931f52f13fa3a9dc$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a75d7e0eba6a1f4a6b03546d';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a77c00829eecde4eeb0dd206' and md5(to_jsonb(t)::text)='486e3603ead6a17a24f7f8043d306d5c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a77c00829eecde4eeb0dd206';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_7d9e695b51075962$[{"id":"legacy-bonus-0","kind":"passive","name":"AC","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Obtienes un bonificador a la CA mientras lleves esta armadura. El bonificador depende de su rareza.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_7d9e695b51075962$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a77c00829eecde4eeb0dd206';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a7f27ead1cc4e65c9c4bb23e' and md5(to_jsonb(t)::text)='6f5e501761c9d7d0ea19e5ab4b32371a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a7f27ead1cc4e65c9c4bb23e';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_420ed0d392688941$[{"id":"official-base-table","rows":[["Cerbatana","10 po","1 lb","1 perforante","+0","Munición, Recarga","25/100"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-loading","text":"Recarga. Debido al tiempo que requiere recargar un arma con esta propiedad, cuando utilices una acción, acción adicional o reacción para atacar con ella, solo podrás disparar una unidad de munición, incluso aunque normalmente pudieras hacer más de un ataque.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_420ed0d392688941$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_e4b7487e601b0af6$["official-base-table","property-ammunition","property-loading","family-rule"]$text_e4b7487e601b0af6$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a7f27ead1cc4e65c9c4bb23e';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a7fbc04fda77cc66426fa9c3' and md5(to_jsonb(t)::text)='9f57d188d2d20b55ae05ba7ad6db3282')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a7fbc04fda77cc66426fa9c3';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(payload,'{features}',$text_2002332186012da1$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves puesto este cinturón, obtienes los siguientes beneficios: • Tu puntuación de Constitución aumenta en 2, hasta un máximo de 20. • Tienes ventaja en las pruebas de Carisma (Persuasión) en las que interactúes con enanos. Además, mientras te sintonices con el cinturón, tendrás un 50 % de probabilidad de que cada día al amanecer te crezca una barba completa, si normalmente podrías tenerla. Si ya tienes una, se volverá visiblemente más densa.\n\nSi no eres enano, obtendrás los siguientes beneficios adicionales mientras lleves puesto el cinturón: • Tienes ventaja en las tiradas de salvación contra veneno y posees resistencia al daño de veneno. • Tienes visión en la oscuridad hasta 18 m. • Puedes hablar, leer y escribir en enano.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_2002332186012da1$::jsonb,true),'{rules,personalDescription}',$text_1c787b5443ef4999$"Mientras lleves este cinturón, obtendrás los siguientes beneficios:\nTu puntuación de Constitución aumenta en 2, hasta un máximo de 20. Tienes ventaja en las pruebas de Carisma (Persuasión) en las que interactúes con enanos.\nAdemás, mientras permanezcas sintonizado con el cinturón, posees un 50 % de probabilidades de que cada día al alba te crezca una barba completa, si normalmente podrías tenerla. Si ya tienes una, se volverá considerablemente más densa.\nSi no eres enano obtendrás los siguientes beneficios adicionales:\nTienes ventaja en las tiradas de salvación contra veneno y posees resistencia al daño de veneno.\nVisión en la Oscuridad hasta una distancia de 60 pies.\nPuedes hablar, leer y escribir en común y enano."$text_1c787b5443ef4999$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a7fbc04fda77cc66426fa9c3';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a953a6430afcb4161c27bed0' and md5(to_jsonb(t)::text)='a3f0af1d6cdba218bbd965a39a2c937c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:a953a6430afcb4161c27bed0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_34385d6556229aa6$[{"id":"legacy-bonus-0","kind":"passive","name":"All","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga un bono de +1 a todas las tiradas de salvación.","showInActions":false},{"id":"legacy-bonus-1","kind":"passive","name":"AC","uses":null,"order":1,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Otorga una bonificación de +1 a la CA.","showInActions":false},{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, recibirás un bonificador de +1 a la CA y a las tiradas de salvación.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_34385d6556229aa6$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:a953a6430afcb4161c27bed0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ab11ee9a5facf012c567cb18' and md5(to_jsonb(t)::text)='dbc1e1cddf771ebb05ec59f5fc8f9b83')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:ab11ee9a5facf012c567cb18';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{description}',$text_5597e5e622a5da4b$"Objeto · Precio base · Peso\nManta · 5 pp · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$text_5597e5e622a5da4b$::jsonb,true),'{rules,definition,description}',$text_4c28cfceb2026d1c$[{"id":"official-table","rows":[["Manta","5 pp","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$text_4c28cfceb2026d1c$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_b507874e9dab9bc1$["official-table"]$text_b507874e9dab9bc1$::jsonb?id),jsonb_build_array('official-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ab11ee9a5facf012c567cb18';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:abd56d7599c6230266eae7ea' and md5(to_jsonb(t)::text)='359203cc149dcef2a4976ecca23960b2')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:abd56d7599c6230266eae7ea';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_c177eb09f8c78bc3$[{"id":"critical-protection","kind":"passive","name":"Protección frente a críticos","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Esta armadura viene reforzada con adamantina, una de las sustancias más duras que existen. Mientras la lleves puesta, cualquier crítico contra ti se convierte en un impacto normal.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_c177eb09f8c78bc3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:abd56d7599c6230266eae7ea';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ac0f80fd1c0f1c938d30b0a8' and md5(to_jsonb(t)::text)='e4288d5b3591982e172cab624021bf2a')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:ac0f80fd1c0f1c938d30b0a8';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_54a737b808cf4ff1$[{"id":"restrain-target","kind":"other","name":"Apresar con la red","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Red. Una criatura Grande o más pequeña que sea impactada por una red quedará apresada hasta ser liberada. Esta arma no tendrá efecto sobre objetivos sin forma definida o que sean de tamaño Enorme o mayor. Una criatura puede emplear su acción para hacer una prueba de Fuerza con CD 10. Si tiene éxito, podrá liberarse a sí misma o a otra criatura dentro de su alcance. Infligir 5 de daño cortante a la red (CA 10) también liberará a la criatura sin causarle daño alguno, pondrá fin al efecto y destruirá la red. Cuando utilices una acción, una acción adicional o una reacción para atacar con una red, solo podrás realizar un ataque, incluso aunque normalmente pudieras hacer más de uno.\n\nSolo un ataque por acción, acción adicional o reacción. Liberar con acción y Fuerza CD 10, o destruir la red (CA 10) con 5 de daño cortante. No se inflige ese daño a la criatura.\n\nDuración: Hasta ser liberada.\n\nAlcance: 5/15 pies.","showInActions":false}]$text_54a737b808cf4ff1$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ac0f80fd1c0f1c938d30b0a8';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae8df89f9da41aae9d719be2' and md5(to_jsonb(t)::text)='8107025fc91a9b95d4c627fbce879bef')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:ae8df89f9da41aae9d719be2';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_f76b4d01d2e7fa71$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras esté encendida, esta linterna sorda luce durante 6 horas con 0,5 l de aceite e ilumina un radio de 9 m con luz brillante y otros 9 m con luz tenue. Las criaturas y objetos invisibles serán visibles mientras permanezcan iluminados por la luz brillante de la linterna. Puedes usar una acción para cubrir la abertura con la tapa y hacer que solo emita luz tenue en un radio de 1,5 m.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_f76b4d01d2e7fa71$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae8df89f9da41aae9d719be2';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae9631af3d28e537066aa759' and md5(to_jsonb(t)::text)='79207b2b4cb4ed8fd6528ed2bca3082c')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:ae9631af3d28e537066aa759';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_4491325648aaeb72$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Recibes un bonificador de +1 a las tiradas de ataque y de daño que hagas con esta arma mágica.\n\nPuedes utilizar una acción para que un veneno denso y negro impregne la hoja. El veneno permanecerá durante 1 minuto o hasta que un ataque con esta arma impacte a una criatura. Esa criatura deberá superar una tirada de salvación de Constitución con CD 15 o recibirá 2d10 de daño de veneno y quedará envenenada durante 1 minuto. La daga no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_4491325648aaeb72$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:ae9631af3d28e537066aa759';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aea59c66b9746d54d96a91a0' and md5(to_jsonb(t)::text)='f9cba26c3536ea6276eafd17e9d62ebf')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:aea59c66b9746d54d96a91a0';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_728c804716077606$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Puedes respirar debajo del agua durante 1 hora tras beber esta poción. Su líquido verde turbio huele a mar y en él flota una burbuja con aspecto de medusa.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_728c804716077606$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aea59c66b9746d54d96a91a0';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aeb6ec2ff9a2adb5c0b4c021' and md5(to_jsonb(t)::text)='b14ff1cce2e10ecae843f3c47dcb2571')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:aeb6ec2ff9a2adb5c0b4c021';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_d4fdc8789d3c09e3$[{"id":"official-2014-rule","kind":"action","name":"Beber o administrar","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando bebas esta poción, obtendrás una velocidad volando igual a tu velocidad caminando durante 1 hora y podrás levitar. Si te encuentras en pleno vuelo cuando el efecto de la poción termine, te caerás salvo que cuentes con otros medios que te mantengan en el aire. El líquido transparente de esta poción flota en la parte superior del frasco y tiene impurezas blancas con forma de nube.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":true}]$text_d4fdc8789d3c09e3$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aeb6ec2ff9a2adb5c0b4c021';
if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aec2756204181dbd531cb861' and md5(to_jsonb(t)::text)='ad87fbbfbd2f1404122e1425c4e08325')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:aec2756204181dbd531cb861';end if;update public.campaign_content_entries set payload=jsonb_set(jsonb_set(jsonb_set(payload,'{features}',$text_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$text_4543b46f281f3b43$::jsonb,true),'{rules,definition,description}',$text_0a21498536d364a5$[{"id":"official-base-table","rows":[["Arco corto","25 po","2 lb","1d6 perforante","+0","Munición, A dos manos","80/320"]],"type":"table","columns":["Objeto base","Precio del objeto mundano","Peso","Daño base","Bonificación mágica al ataque","Propiedades","Alcance normal/largo (pies)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"property-ammunition","text":"Munición. Solo puedes realizar un ataque a distancia usando un arma con esta propiedad si tienes munición para ella. Cada vez que hagas un ataque, gastarás una unidad de munición. Extraer la munición de una aljaba, un estuche u otro contenedor forma parte del ataque (necesitas una mano libre para cargar un arma a una mano). Al final del combate, podrás recuperar la mitad de la munición usada si dedicas un minuto a buscar en el campo de batalla. Si empleas un arma con esta propiedad para hacer un ataque cuerpo a cuerpo, se considerará un arma improvisada (consulta “Armas improvisadas” en esta misma sección). Además, una honda deberá estar cargada para hacer daño cuando se utilice de esta forma.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"property-two-handed","text":"A dos manos. Estas armas requieren el uso de las dos manos.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"},{"id":"family-rule","text":"Cuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.","type":"paragraph","section":"rules","sourceIds":["dmg-2014-vicious"],"provenance":"reviewed-translation"}]$text_0a21498536d364a5$::jsonb,true),'{rules,definition,capabilities}',(select coalesce(jsonb_agg(cap||jsonb_build_object('textBlockIds',coalesce((select jsonb_agg(id) from jsonb_array_elements_text(cap->'textBlockIds')id where $text_8cd0df65830d6096$["official-base-table","property-ammunition","property-two-handed","family-rule"]$text_8cd0df65830d6096$::jsonb?id),jsonb_build_array('official-base-table')))),'[]'::jsonb) from jsonb_array_elements(payload#>'{rules,definition,capabilities}')cap),true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:aec2756204181dbd531cb861';
