if not exists(select 1 from public.campaign_content_entries t where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b05f5e537ecf92db2ca2ae7e' and md5(to_jsonb(t)::text)='8977c25aed33a568fee21b46f32b379b')then raise exception 'ITEM_TEXT_CONFLICT:ece:official:equipment:es:b05f5e537ecf92db2ca2ae7e';end if;update public.campaign_content_entries set payload=jsonb_set(payload,'{features}',$text_5578d9431671b5ce$[{"id":"official-assisted-rule","kind":"other","name":"Reglas del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras lleves esta capa, tendrás ventaja en las pruebas de Destreza (Sigilo). En una zona de luz tenue o de oscuridad, puedes agarrar los extremos de la capa con ambas manos y usarla para volar a una velocidad de 12 m. Si sueltas los extremos de la capa mientras vuelas de esta forma o si ya no te encuentras bajo luz tenue u oscuridad, perderás esta velocidad volando.\n\nMientras lleves puesta la capa en una zona de luz tenue u oscuridad, podrás usar tu acción para lanzar polimorfar sobre ti y transformarte en un murciélago. En forma de murciélago, conservas tus puntuaciones de Inteligencia, Sabiduría y Carisma. La capa no puede volver a emplearse de esta manera hasta el siguiente amanecer.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$text_5578d9431671b5ce$::jsonb,true),revision=revision+1,updated_at=statement_timestamp() where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='equipment' and content_key='official:equipment:es:b05f5e537ecf92db2ca2ae7e';
